import{_ as r,l,o as e,c as n,v as t,p as s,x as i,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"折反射物镜设计","description":"","frontmatter":{"title":"折反射物镜设计","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/catadioptric-lens-design.md","filePath":"litho/catadioptric-lens-design.md","lastUpdated":1789023840000}'),p={name:"litho/catadioptric-lens-design.md"};function m(_,a,A,E,u,f){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="折反射物镜设计" tabindex="-1">折反射物镜设计 <a class="header-anchor" href="#折反射物镜设计" aria-label="Permalink to &quot;折反射物镜设计&quot;">​</a></h1><div class="epigraph"><p>193 nm 高 NA 浸没物镜不是一串透镜堆到底：反射面用来折光路、控色差，折射面用来收 NA。折反射是材料与像差预算的解，不是外观。</p><footer>—— 对照蔡司投影物镜公开的 catadioptric 架构；[蔡司 EUV 光学](/litho/zeiss-euv-optics) 是多层反射的另一条路</footer></div><p><a href="/litho/source-power-stability">上一课</a>收束激光稳定。照明已经进狭缝；缺口是<strong>谁把掩模傅里叶面成像到晶圆</strong>。本课钉 193 nm 浸没用的折反射（catadioptric）物镜：反射+折射，不重推 <a href="/litho/lens-na">NA</a> 或瑞利公式。后课加热、操纵器、材料都默认这台镜头的几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯折射在 193 nm 要很多 CaF₂ / 熔石英，色差与质量迅速失控；纯反射（EUV 那套多层）在 DUV 不是这条产线。折反射用凹面镜转折光路、减少玻璃厚度，折射组提供可变光焦度与浸没最后一片。缺口不是「镜头有多少片」的广告，而是为何必须混合。</p><p><span class="marginnote">浸没最后一片与水接触，材料、镀膜、机械是流体课已经埋的接口。本课只谈投影组整体形态，不写喷淋头。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计自由度：镜面曲率、透镜组、偏振控制、狭缝视场。扫描机只照明狭缝高的环形视场，物镜按扫描缝优化，不是全圆显微镜。装调：各面间隔与倾角进像差表，后课操纵器微调。</p>',8)),(e(),s(h,null,{default:i(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%82%85%E9%87%8C%E5%8F%B6%22%5D%20--%3E%20CAT%5B%22%E6%8A%98%E5%8F%8D%E5%B0%84%E7%BB%84%22%5D%0A%20%20CAT%20--%3E%20IMM%5B%22%E6%B5%B8%E6%B2%A1%E6%9C%AB%E7%89%87%22%5D%0A%20%20IMM%20--%3E%20WAF%5B%22%E6%99%B6%E5%9C%86%E5%83%8F%E9%9D%A2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反射面无色散，帮色差；但仍有中心遮拦或离轴视场约束，必须用折射补场曲与畸变。高 NA 下矢量效应在末片最剧，见 <a href="/litho/immersion-vector-imaging">浸没矢量成像</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>EUV 投影是全反射多层，本课不混写。下一课透镜加热：即使设计理想，193 nm 吸收仍把镜头烤变形。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>193 nm 高 NA 浸没物镜走折反射，为材料与色差，不为造型。</li><li>扫描狭缝视场决定优化域。</li><li>出处：蔡司 / 浸没物镜公开架构；NA 课。</li></ul>',6))])}const b=r(p,[["render",m]]);export{B as __pageData,b as default};
